/// ```
#[macro_export]
macro_rules! vstack {
    ($($child:expr),* $(,)?) => {
        $crate::VStack::new().children($crate::vec![$($crate::Box::new($child)),*])
    };
}

/// Build a horizontal stack from a comma-separated list of views.
///
/// See [`vstack!`] for details.
#[macro_export]
macro_rules! hstack {
    ($($child:expr),* $(,)?) => {
        $crate::HStack::new().children($crate::vec![$($crate::Box::new($child)),*])
    };
