//! Batch wire format: encode/decode opcodes + arena delta into network batches.

use alloc::vec::Vec;
use pathland_opcode::{Frame, Opcode};

use crate::{BATCH_MAGIC, BATCH_VERSION};

/// Fixed header byte length: magic(4) + version(2) + flags(2) + frameCount(4) + opcodeCount(4).
pub const BATCH_HEADER: usize = 16;

/// Errors produced while decoding a network batch.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BatchError {
    /// The batch is shorter than the fixed header.
    Truncated,
    /// The batch magic does not match `BATCH_MAGIC`.
    BadMagic,
    /// The batch version is not supported.
    BadVersion,
    /// The opcode payload is truncated (opcodeCount × 16 exceeds the buffer).
    BadOpcodeCount,
    /// The arena delta length exceeds the remaining buffer.
    BadArenaLen,
}

/// A decoded network batch: opcodes plus a mirrored arena, exposed as a
/// `pathland_opcode::Frame` so consumers (`RenderTree::apply_frame`) work
/// exactly as with shared-memory frames.
#[derive(Debug)]
pub struct Batch<'a> {
    frame: Frame<'a>,
    frame_count: u32,
    flags: u16,
}

impl<'a> Batch<'a> {
    /// The opcodes carried by this batch, in order.
    pub fn opcodes(&self) -> impl Iterator<Item = Opcode> + '_ {
        self.frame.opcodes()
    }

    /// Number of opcodes in the batch.
    pub fn len(&self) -> usize {
        self.frame.len()
    }

    pub fn is_empty(&self) -> bool {
        self.frame.is_empty()
    }

    /// The guest frame count the batch spans.
    pub fn frame_count(&self) -> u32 {
        self.frame_count
    }

    /// Direction flags (see [`crate::direction`]).
    pub fn flags(&self) -> u16 {
        self.flags
    }

    /// View this batch as a `Frame` (the transport seam).
    pub fn as_frame(&self) -> &Frame<'a> {
        &self.frame
    }

    /// Read an arena entry by offset (see `Frame::arena_get`).
    pub fn arena_get(&self, offset: u32) -> Result<&'a [u8], pathland_opcode::ArenaError> {
        self.frame.arena_get(offset)
    }

    /// Read an arena string by offset.
    pub fn arena_str(&self, offset: u32) -> Result<&'a str, pathland_opcode::ArenaError> {
        self.frame.arena_str(offset)
    }
}

/// Serialize one batch from opcodes + an arena delta (bytes appended since the
/// previous batch). Stateless; see [`BatchEncoder`] for cursor tracking.
pub fn encode_batch(
    frame_count: u32,
    flags: u16,
    opcodes: &[Opcode],
    arena_delta: &[u8],
) -> Vec<u8> {
    let mut out = Vec::with_capacity(BATCH_HEADER + opcodes.len() * Opcode::SIZE + arena_delta.len() + 4);
    out.extend_from_slice(&BATCH_MAGIC.to_le_bytes());
    out.extend_from_slice(&BATCH_VERSION.to_le_bytes());
    out.extend_from_slice(&flags.to_le_bytes());
    out.extend_from_slice(&frame_count.to_le_bytes());
    out.extend_from_slice(&(opcodes.len() as u32).to_le_bytes());
    for op in opcodes {
        out.extend_from_slice(&op.to_bytes());
    }
    out.extend_from_slice(&(arena_delta.len() as u32).to_le_bytes());
    out.extend_from_slice(arena_delta);
    out
}

/// Parse a batch header, returning `(flags, frame_count, opcodes_bytes, arena_delta_bytes)`.
fn parse(bytes: &[u8]) -> Result<(u16, u32, &[u8], &[u8]), BatchError> {
    if bytes.len() < BATCH_HEADER {
        return Err(BatchError::Truncated);
    }
    let magic = u32::from_le_bytes(bytes[0..4].try_into().unwrap());
    if magic != BATCH_MAGIC {
        return Err(BatchError::BadMagic);
    }
    let version = u16::from_le_bytes(bytes[4..6].try_into().unwrap());
    if version != BATCH_VERSION {
        return Err(BatchError::BadVersion);
    }
    let flags = u16::from_le_bytes(bytes[6..8].try_into().unwrap());
    let frame_count = u32::from_le_bytes(bytes[8..12].try_into().unwrap());
    let opcode_count = u32::from_le_bytes(bytes[12..16].try_into().unwrap()) as usize;

    let opcodes_bytes = opcode_count
        .checked_mul(Opcode::SIZE)
        .ok_or(BatchError::BadOpcodeCount)?;
    let opcodes_start = BATCH_HEADER;
    let opcodes_end = opcodes_start
        .checked_add(opcodes_bytes)
        .ok_or(BatchError::BadOpcodeCount)?;
    if opcodes_end > bytes.len() {
        return Err(BatchError::BadOpcodeCount);
    }
    let arena_len_pos = opcodes_end;
    if arena_len_pos + 4 > bytes.len() {
        return Err(BatchError::BadArenaLen);
    }
    let arena_len = u32::from_le_bytes(bytes[arena_len_pos..arena_len_pos + 4].try_into().unwrap())
        as usize;
    let arena_start = arena_len_pos + 4;
    let arena_end = arena_start
        .checked_add(arena_len)
        .ok_or(BatchError::BadArenaLen)?;
    if arena_end > bytes.len() {
        return Err(BatchError::BadArenaLen);
    }

    Ok((
        flags,
        frame_count,
        &bytes[opcodes_start..opcodes_end],
        &bytes[arena_start..arena_end],
    ))
}

/// A streamed network-batch encoder.
///
/// Tracks the last arena length so successive batches carry only the bytes
/// appended to the bump arena since the previous batch. If the arena is reset
/// (shrank — see `META::RESET`), the full used arena is sent and tracking
/// restarts.
#[derive(Debug, Default)]
pub struct BatchEncoder {
    last_arena_len: usize,
}

impl BatchEncoder {
    /// Create a fresh encoder (no arena bytes sent yet).
    pub fn new() -> Self {
        Self { last_arena_len: 0 }
    }

    /// Encode a frame's opcodes plus the arena bytes appended since the last
    /// call. `arena_used` is the arena region's used portion (`[0..cursor)`).
    pub fn encode(&mut self, frame_count: u32, opcodes: &[Opcode], arena_used: &[u8]) -> Vec<u8> {
        let delta = if arena_used.len() >= self.last_arena_len {
            &arena_used[self.last_arena_len..]
        } else {
            // Arena shrank (a reset): send the full used arena again.
            arena_used
        };
        let bytes = encode_batch(frame_count, crate::direction::GUEST_TO_HOST, opcodes, delta);
        self.last_arena_len = arena_used.len();
        bytes
    }

    /// The arena length already shipped (diagnostics).
    pub fn arena_sent(&self) -> usize {
        self.last_arena_len
    }
}

/// A streamed network-batch decoder.
///
/// Maintains a **mirrored arena**: each batch's arena delta is appended, so
/// absolute `arenaRef` offsets resolve exactly as in shared memory. When a
/// batch contains `META::RESET`, the mirror is cleared before appending.
#[derive(Debug, Default)]
pub struct BatchDecoder {
    arena: Vec<u8>,
}

impl BatchDecoder {
    /// Create an empty decoder.
    pub fn new() -> Self {
        Self { arena: Vec::new() }
    }

    /// Decode a batch, appending its arena delta to the mirror.
    ///
    /// The returned `Batch` borrows `bytes` (opcodes) and this decoder (arena);
    /// keep both alive while consuming it.
    pub fn decode<'a>(&'a mut self, bytes: &'a [u8]) -> Result<Batch<'a>, BatchError> {
        let (flags, frame_count, opcodes_bytes, arena_delta) = parse(bytes)?;

        // A META::RESET in the batch clears the renderer; reset the arena mirror
        // to match (offsets restart at 0 after a reset).
        let opcode_count = opcodes_bytes.len() / Opcode::SIZE;
        let reset = (0..opcode_count).any(|i| {
            let op = Opcode::from_bytes(opcodes_bytes[i * Opcode::SIZE..(i + 1) * Opcode::SIZE].try_into().unwrap());
            op.category() == pathland_opcode::category::META
                && op.command() == pathland_opcode::meta::RESET
        });
        if reset {
            self.arena.clear();
        }
        self.arena.extend_from_slice(arena_delta);

        let frame = Frame::from_parts(opcodes_bytes, &self.arena, 0, opcodes_bytes.len());
        Ok(Batch {
            frame,
            frame_count,
            flags,
        })
    }

    /// The mirrored arena length (diagnostics).
    pub fn arena_len(&self) -> usize {
        self.arena.len()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use pathland_opcode::{category, meta, Opcode};

    fn sample_opcodes() -> Vec<Opcode> {
        vec![
            Opcode::new(category::TREE, 0x01, 0, 1, 0x0002, 0),
            Opcode::new(category::STYLE, 0x03, 0, 1, 0, 0),
        ]
    }

    #[test]
    fn encode_then_decode_round_trips() {
        let opcodes = sample_opcodes();
        let arena_delta = [5u8, 0, 0, 0, b'h', b'e', b'l', b'l', b'o'];
        let bytes = encode_batch(7, 0, &opcodes, &arena_delta);

        let mut decoder = BatchDecoder::new();
        let batch = decoder.decode(&bytes).unwrap();
        assert_eq!(batch.frame_count(), 7);
        assert_eq!(batch.len(), opcodes.len());
        let decoded: Vec<Opcode> = batch.opcodes().collect();
        assert_eq!(decoded, opcodes);
        assert_eq!(decoder.arena_len(), arena_delta.len());
        assert_eq!(batch.arena_str(1).unwrap(), "hello");
    }

    #[test]
    fn bad_magic_is_rejected() {
        let opcodes = sample_opcodes();
        let mut bytes = encode_batch(0, 0, &opcodes, &[]);
        bytes[0] = 0xFF;
        assert_eq!(
            BatchDecoder::new().decode(&bytes).unwrap_err(),
            BatchError::BadMagic
        );
    }

    #[test]
    fn truncated_is_rejected() {
        assert_eq!(
            BatchDecoder::new().decode(&[0u8; 4]).unwrap_err(),
            BatchError::Truncated
        );
    }

    #[test]
    fn encoder_tracks_arena_delta() {
        let opcodes = sample_opcodes();
        let mut enc = BatchEncoder::new();
        let first = enc.encode(1, &opcodes, &[5u8, 0, 0, 0, b'a']);
        let second = enc.encode(2, &opcodes, &[5u8, 0, 0, 0, b'a', b'b', b'c', b'd', b'e']);

        let mut decoder = BatchDecoder::new();
        let b1 = decoder.decode(&first).unwrap();
        assert_eq!(decoder.arena_len(), 5);
        assert_eq!(b1.arena_str(1).unwrap(), "a");
        let b2 = decoder.decode(&second).unwrap();
        assert_eq!(decoder.arena_len(), 9);
        // Second batch carries only the appended 4 bytes; the mirror now has both.
        assert_eq!(b2.arena_str(1).unwrap(), "abcde");
    }

    #[test]
    fn reset_clears_arena_mirror() {
        let reset = Opcode::new(category::META, meta::RESET, 0, 0, 0, 0);
        let mut enc = BatchEncoder::new();
        let first = enc.encode(1, &[reset], &[5u8, 0, 0, 0, b'a']);
        // After reset the used arena restarts; send a fresh entry at offset 0.
        let after_reset = enc.encode(2, &[reset], &[3u8, 0, 0, 0, b'x', b'y', b'z']);

        let mut decoder = BatchDecoder::new();
        decoder.decode(&first).unwrap();
        assert_eq!(decoder.arena_len(), 5);
        decoder.decode(&after_reset).unwrap();
        // Mirror cleared on RESET, then appended the 3 new bytes.
        assert_eq!(decoder.arena_len(), 3);
    }
}

//! Batching policy and buffering for network transport.
//!
//! `Batcher` accumulates frames against a [`BatchPolicy`] and flushes a single
//! serialized batch when either the time interval since the first buffered
//! opcode elapses **or** the accumulated byte size reaches the threshold —
//! first trigger wins.

use alloc::vec::Vec;
use std::time::{Duration, Instant};

use pathland_opcode::{Opcode, Frame};

use crate::batch::encode_batch;
use crate::direction::GUEST_TO_HOST;

/// Default time interval before a batch is flushed (4 ms).
pub const DEFAULT_MAX_INTERVAL: Duration = Duration::from_millis(4);
/// Default max batch byte size (conservative network frame / MTU).
pub const DEFAULT_MAX_BATCH_BYTES: usize = 1400;

/// Flush thresholds for network batching.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BatchPolicy {
    /// Flush when this much time has elapsed since the first buffered opcode.
    pub max_interval: Duration,
    /// Flush when the accumulated batch reaches this many bytes.
    pub max_batch_bytes: usize,
}

impl BatchPolicy {
    /// Create a policy from a time interval and a max batch size.
    pub const fn new(max_interval: Duration, max_batch_bytes: usize) -> Self {
        Self {
            max_interval,
            max_batch_bytes,
        }
    }

    /// The default policy: 4 ms interval, 1400-byte batches.
    pub const fn default_policy() -> Self {
        Self::new(DEFAULT_MAX_INTERVAL, DEFAULT_MAX_BATCH_BYTES)
    }
}

impl Default for BatchPolicy {
    fn default() -> Self {
        Self::default_policy()
    }
}

/// Accumulates frames into a batch and flushes per [`BatchPolicy`].
///
/// The arena is append-only; the batcher ships the bytes appended since the
/// last flush (tracked by arena length). If the arena shrank (a `META::RESET`),
/// the pending arena is reset so the next flush starts fresh.
#[derive(Debug)]
pub struct Batcher {
    policy: BatchPolicy,
    /// Frame count of the last flushed batch.
    frame_count: u32,
    /// Arena bytes appended since the last flush.
    pending_arena: Vec<u8>,
    /// Arena length at the last flush.
    last_arena_len: usize,
    /// When the first opcode of the current batch was buffered.
    started: Option<Instant>,
    /// Time/size trigger helper.
    triggered: bool,
}

impl Batcher {
    /// Create a batcher with the given policy.
    pub fn new(policy: BatchPolicy) -> Self {
        Self {
            policy,
            frame_count: 0,
            pending_arena: Vec::new(),
            last_arena_len: 0,
            started: None,
            triggered: false,
        }
    }

    /// Create a batcher with the default policy (4 ms / 1400 B).
    pub fn default_policy() -> Self {
        Self::new(BatchPolicy::default())
    }

    /// Whether no opcodes are currently buffered.
    pub fn is_empty(&self) -> bool {
        self.pending_arena.is_empty() && self.last_arena_len == 0
    }

    /// Buffered bytes that would be shipped on flush (diagnostics).
    pub fn pending_bytes(&self) -> usize {
        self.pending_arena.len()
    }

    /// Record a frame (opcodes + the arena's used portion `[0..cursor)`),
    /// accumulating the arena delta. Returns `true` if the policy says to flush.
    pub fn push_frame(&mut self, frame_count: u32, opcodes: &[Opcode], arena_used: &[u8]) -> bool {
        if self.started.is_none() {
            self.started = Some(Instant::now());
            self.frame_count = frame_count;
        }
        if arena_used.len() < self.last_arena_len {
            // Arena was reset; restart the pending buffer.
            self.pending_arena.clear();
            self.last_arena_len = 0;
        }
        self.pending_arena.extend_from_slice(&arena_used[self.last_arena_len..]);
        self.last_arena_len = arena_used.len();

        let opcodes_bytes = opcodes.len() * Opcode::SIZE;
        self.triggered |= self.pending_bytes() + opcodes_bytes >= self.policy.max_batch_bytes;
        self.triggered
    }

    /// Whether the time interval has elapsed since the first buffered opcode.
    pub fn interval_elapsed(&self) -> bool {
        match self.started {
            Some(t) => t.elapsed() >= self.policy.max_interval,
            None => false,
        }
    }

    /// Serialize and reset the current buffer, returning the batch bytes
    /// (or `None` when empty). `force` bypasses the size trigger but still
    /// respects an empty buffer.
    pub fn flush(&mut self, force: bool) -> Option<Vec<u8>> {
        let should_flush = force || self.triggered || self.interval_elapsed();
        if !should_flush || self.started.is_none() {
            return None;
        }
        // Re-serialize opcodes from the caller-provided list is not possible
        // here; frames are pushed as opcodes + arena, so we need the opcode
        // bytes. See `push_opcodes`/`push` for the opcode-bearing API.
        let _ = &self.pending_arena;
        None
    }

    /// Reset all buffered state (after a flush or reset).
    fn reset(&mut self) {
        self.pending_arena.clear();
        self.last_arena_len = 0;
        self.started = None;
        self.triggered = false;
    }
}

//! Batching policy and buffering for network transport.
//!
//! `Batcher` accumulates frames against a [`BatchPolicy`] and flushes a single
//! serialized batch when either the time interval since the first buffered
//! opcode elapses **or** the accumulated byte size reaches the threshold —
//! first trigger wins.

use alloc::vec::Vec;
use std::time::{Duration, Instant};

use pathland_opcode::{Frame, Opcode};

use crate::batch::encode_batch;
use crate::direction::GUEST_TO_HOST;

/// Default time interval before a batch is flushed (4 ms).
pub const DEFAULT_MAX_INTERVAL: Duration = Duration::from_millis(4);
/// Default max batch byte size (conservative network frame / MTU).
pub const DEFAULT_MAX_BATCH_BYTES: usize = 1400;

/// Flush thresholds for network batching.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BatchPolicy {
    /// Flush when this much time has elapsed since the first buffered opcode.
    pub max_interval: Duration,
    /// Flush when the accumulated batch reaches this many bytes.
    pub max_batch_bytes: usize,
}

impl BatchPolicy {
    /// Create a policy from a time interval and a max batch size.
    pub const fn new(max_interval: Duration, max_batch_bytes: usize) -> Self {
        Self {
            max_interval,
            max_batch_bytes,
        }
    }

    /// The default policy: 4 ms interval, 1400-byte batches.
    pub const fn default_policy() -> Self {
        Self::new(DEFAULT_MAX_INTERVAL, DEFAULT_MAX_BATCH_BYTES)
    }
}

impl Default for BatchPolicy {
    fn default() -> Self {
        Self::default_policy()
    }
}

/// Accumulates frames into a batch and flushes per [`BatchPolicy`].
///
/// The arena is append-only; the batcher ships the bytes appended since the
/// last flush (tracked by arena length). If the arena shrank (a `META::RESET`),
/// the pending arena is reset so the next flush starts fresh.
#[derive(Debug)]
pub struct Batcher {
    policy: BatchPolicy,
    /// Frame count of the first buffered frame.
    frame_count: u32,
    /// Opcodes buffered since the last flush.
    opcodes: Vec<Opcode>,
    /// Arena bytes appended since the last flush.
    pending_arena: Vec<u8>,
    /// Arena length at the last flush.
    last_arena_len: usize,
    /// When the first opcode of the current batch was buffered.
    started: Option<Instant>,
    /// Size trigger latched on push.
    size_triggered: bool,
}

impl Batcher {
    /// Create a batcher with the given policy.
    pub fn new(policy: BatchPolicy) -> Self {
        Self {
            policy,
            frame_count: 0,
            opcodes: Vec::new(),
            pending_arena: Vec::new(),
            last_arena_len: 0,
            started: None,
            size_triggered: false,
        }
    }

    /// Create a batcher with the default policy (4 ms / 1400 B).
    pub fn default_policy() -> Self {
        Self::new(BatchPolicy::default())
    }

    /// Whether no opcodes are currently buffered.
    pub fn is_empty(&self) -> bool {
        self.opcodes.is_empty()
    }

    /// Number of opcodes buffered since the last flush (diagnostics).
    pub fn pending_opcodes(&self) -> usize {
        self.opcodes.len()
    }

    /// Approximate bytes that would be shipped on flush (diagnostics).
    pub fn pending_bytes(&self) -> usize {
        self.opcodes.len() * Opcode::SIZE + self.pending_arena.len() + crate::batch::BATCH_HEADER + 4
    }

    /// Record a frame (opcodes + the arena's used portion `[0..cursor)`),
    /// accumulating the arena delta. Returns `true` if the size trigger fired.
    pub fn push_frame(&mut self, frame_count: u32, opcodes: &[Opcode], arena_used: &[u8]) -> bool {
        if self.started.is_none() {
            self.started = Some(Instant::now());
            self.frame_count = frame_count;
        }
        if arena_used.len() < self.last_arena_len {
            // Arena was reset; restart the pending buffer.
            self.pending_arena.clear();
            self.last_arena_len = 0;
        }
        self.pending_arena.extend_from_slice(&arena_used[self.last_arena_len..]);
        self.last_arena_len = arena_used.len();
        self.opcodes.extend_from_slice(opcodes);

        self.size_triggered |= self.pending_bytes() >= self.policy.max_batch_bytes;
        self.size_triggered
    }

    /// Whether the time interval has elapsed since the first buffered opcode.
    pub fn interval_elapsed(&self) -> bool {
        match self.started {
            Some(t) => t.elapsed() >= self.policy.max_interval,
            None => false,
        }
    }

    /// Serialize and reset the current buffer, returning the batch bytes.
    ///
    /// Flushes when `force` is true or either policy trigger fired. Returns
    /// `None` when nothing is buffered.
    pub fn flush(&mut self, force: bool) -> Option<Vec<u8>> {
        if self.opcodes.is_empty() {
            return None;
        }
        let should_flush = force || self.size_triggered || self.interval_elapsed();
        if !should_flush {
            return None;
        }
        let bytes = encode_batch(
            self.frame_count,
            GUEST_TO_HOST,
            &self.opcodes,
            &self.pending_arena,
        );
        self.opcodes.clear();
        self.pending_arena.clear();
        self.last_arena_len = 0;
        self.started = None;
        self.size_triggered = false;
        Some(bytes)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use pathland_opcode::{category, Opcode};

    fn op(n: u32) -> Opcode {
        Opcode::new(category::TREE, 0x01, 0, n, 0x0002, 0)
    }

    fn empty_arena() -> &'static [u8] {
        &[]
    }

    #[test]
    fn size_trigger_flushes() {
        // Tiny batch size: one opcode (16 B) exceeds it.
        let policy = BatchPolicy::new(Duration::from_secs(60), 8);
        let mut batcher = Batcher::new(policy);
        batcher.push_frame(1, &[op(1)], empty_arena());
        assert!(batcher.size_triggered);
        let bytes = batcher.flush(false).expect("size trigger should flush");
        assert!(!bytes.is_empty());
        assert!(batcher.is_empty());
    }

    #[test]
    fn no_flush_when_under_policy() {
        let policy = BatchPolicy::new(Duration::from_secs(60), 10_000);
        let mut batcher = Batcher::new(policy);
        batcher.push_frame(1, &[op(1)], empty_arena());
        assert!(!batcher.size_triggered);
        assert!(batcher.flush(false).is_none());
        // Force flush drains it.
        let bytes = batcher.flush(true).expect("force flush");
        assert!(!bytes.is_empty());
    }

    #[test]
    fn time_trigger_flushes() {
        let policy = BatchPolicy::new(Duration::from_millis(1), 10_000);
        let mut batcher = Batcher::new(policy);
        batcher.push_frame(1, &[op(1)], empty_arena());
        std::thread::sleep(Duration::from_millis(5));
        assert!(batcher.interval_elapsed());
        let bytes = batcher.flush(false).expect("time trigger should flush");
        assert!(!bytes.is_empty());
    }

    #[test]
    fn flush_empty_returns_none() {
        let mut batcher = Batcher::new(BatchPolicy::default());
        assert!(batcher.flush(true).is_none());
    }

    #[test]
    fn multiple_frames_coalesce_into_one_batch() {
        let policy = BatchPolicy::new(Duration::from_secs(60), 10_000);
        let mut batcher = Batcher::new(policy);
        batcher.push_frame(1, &[op(1)], empty_arena());
        batcher.push_frame(2, &[op(2), op(3)], empty_arena());
        assert_eq!(batcher.pending_opcodes(), 3);
        let bytes = batcher.flush(true).unwrap();
        // Header(16) + 3 opcodes(48) + arenaLen(4) + 0 arena.
        assert_eq!(bytes.len(), 16 + 48 + 4);
        assert!(batcher.is_empty());
    }
}

