impl core::fmt::Debug for Event {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match self {
            Event::PointerDown(e) => {
                f.debug_tuple("Event::PointerDown").field(e).finish()
            }
            Event::PointerMove(e) => {
                f.debug_tuple("Event::PointerMove").field(e).finish()
            }
            Event::PointerUp(e) => {
                f.debug_tuple("Event::PointerUp").field(e).finish()
