===================================================================
--- lib/rust/crates/pathland-gtk-demo/src/main.rs	
+++ lib/rust/crates/pathland-gtk-demo/src/main.rs	
@@ -0,0 +1,216 @@
+//! # Pathland GTK4 desktop demo
+//!
+//! A native GTK4 app that consumes the Pathland components through the WIT
+//! world. The developer authors the UI with the SwiftUI-style DSL; the tree
+//! flows through the bridge into the WASM guest component (`pathland-guest`),
+//! which emits declarative opcodes. The host decodes the emitted batch into a
+//! `RenderTree` and renders it with GTK widgets — no host-side reimplementation
+//! of layout.
+//!
+//! Interaction: the button click dispatches a raw `EVENT` into the guest, which
+//! routes it back to the app via `app.on-event`; the app re-authors the DSL
+//! tree and re-emits, so the guest diffs and the renderer updates.
+
+use std::cell::RefCell;
+use std::rc::Rc;
+
+use gtk::prelude::*;
+use gtk::{Align, Application, ApplicationWindow, Box as GtkBox, Label, Orientation};
+use pathland_host::RenderTree;
+use pathland_transport::BatchDecoder;
+use pathland_view::{assign_ids, button, hstack, text, vstack, Node, View, ViewExt};
+use pathland_wit_host::{types, Event, GuestHost};
+
+/// Component bytes are built by `cargo component build -p pathland-guest`.
+const GUEST_WASM: &str =
+    concat!(env!("CARGO_MANIFEST_DIR"), "/../../target/wasm32-wasip1/debug/pathland_guest.wasm");
+
+const APP_ID: &str = "org.pathland.GtkDemo";
+
+/// Build the DSL tree for the current counter value. This is the developer's
+/// authoring surface — core views (WIT) and custom views are indistinguishable.
+fn build_tree(count: u32) -> Node {
+    vstack![
+        hstack![
+            text(format!("Count: {}", count).as_str()),
+            button("Increment"),
+        ]
+        .padding(16.0),
+        text("Pathland · GTK4 · WIT").color(0xFF_888888),
+    ]
+    .padding(24.0)
+    .build()
+}
+
+/// The demo application: holds the guest host + the current count.
+struct Demo {
+    host: GuestHost,
+    count: u32,
+    /// Button-click callback (set once during UI setup).
+    on_click: Option<Rc<dyn Fn()>>,
+}
+
+fn main() {
+    let app = Application::builder().application_id(APP_ID).build();
+    app.connect_activate(build_ui);
+    app.run();
+}
+
+fn build_ui(app: &Application) {
+    let bytes = std::fs::read(GUEST_WASM).expect("run `cargo component build` first");
+
+    // Shared application state (mutable through Rc<RefCell> across callbacks).
+    let demo = Rc::new(RefCell::new(Demo {
+        host: GuestHost::new(&bytes, DemoApp).unwrap(),
+        count: 0,
+        on_click: None,
+    }));
+
+    let window = ApplicationWindow::builder()
+        .application(app)
+        .title("Pathland GTK4 Demo")
+        .default_width(420)
+        .default_height(220)
+        .build();
+
+    let root = GtkBox::new(Orientation::Vertical, 0);
+    window.set_child(Some(&root));
+
+    // Re-render the current tree through the full pipeline.
+    let demo_ren = Rc::clone(&demo);
+    let root_ren = root.clone();
+    let re_render = move || render(&demo_ren, &root_ren);
+
+    re_render();
+
+    // Button clicks dispatch an EVENT into the guest (routed back via
+    // app.on-event), apply the state change, then re-render.
+    let demo_click = Rc::clone(&demo);
+    let root_click = root.clone();
+    let on_click: Rc<dyn Fn()> = Rc::new(move || {
+        let mut d = demo_click.borrow_mut();
+        let event = types::Event::PointerDown((
+            0,
+            types::Point {
+                x: 0.0,
+                y: 0.0,
+                secondary: false,
+            },
+        ));
+        let _ = d.host.dispatch(&event);
+        d.count = d.count.wrapping_add(1);
+        drop(d);
+        render(&demo_click, &root_click);
+    });
+    demo.borrow_mut().on_click = Some(on_click);
+
+    window.present();
+}
+
+/// Run the pipeline: DSL -> bridge -> guest -> emit -> batch -> decode ->
+/// RenderTree, then rebuild the GTK widget hierarchy.
+fn render(demo: &Rc<RefCell<Demo>>, root: &GtkBox) {
+    let mut d = demo.borrow_mut();
+    let on_click: Option<Rc<dyn Fn()>> = d.on_click.clone();
+    let tree = build_tree(d.count);
+    let mut tree = tree;
+    assign_ids(&mut tree, &mut 1);
+
+    d.host.import_tree(&tree).unwrap();
+    let batch = d.host.emit().unwrap();
+
+    let mut decoder = BatchDecoder::new();
+    let mut render = RenderTree::default();
+    let batch = decoder.decode(&batch).unwrap();
+    render.apply_frame(batch.as_frame());
+
+    while let Some(child) = root.first_child() {
+        root.remove(&child);
+    }
+    if let Some(root_node_id) = render.root().map(|n| n.id) {
+        root.append(&render_node(&render, root_node_id, on_click));
+    }
+    root.show();
+    drop(d);
+}
+
+/// Build a GTK widget subtree for a node id from the `RenderTree`.
+fn render_node(render: &RenderTree, id: u32, on_click: Option<Rc<dyn Fn()>>) -> gtk::Widget {
+    let node = render.node(id).unwrap();
+    match node.component_type {
+        pathland_opcode::component_type::VSTACK => {
+            let bx = GtkBox::new(Orientation::Vertical, spacing(render, id));
+            bx.set_halign(Align::Fill);
+            bx.set_valign(Align::Fill);
+            for child in &node.children {
+                bx.append(&render_node(render, *child, on_click.clone()));
+            }
+            bx.upcast()
+        }
+        pathland_opcode::component_type::HSTACK => {
+            let bx = GtkBox::new(Orientation::Horizontal, spacing(render, id));
+            bx.set_halign(Align::Center);
+            bx.set_valign(Align::Center);
+            for child in &node.children {
+                bx.append(&render_node(render, *child, on_click.clone()));
+            }
+            bx.upcast()
+        }
+        pathland_opcode::component_type::TEXT => {
+            let label = Label::new(Some(node.text.as_deref().unwrap_or("")));
+            apply_text_style(&label, render, id);
+            label.upcast()
+        }
+        pathland_opcode::component_type::BUTTON => {
+            let btn = gtk::Button::with_label(node.text.as_deref().unwrap_or(""));
+            if let Some(cb) = on_click {
+                btn.connect_clicked(move |_| cb());
+            }
+            btn.upcast()
+        }
+        _ => Label::new(Some("")).upcast(),
+    }
+}
+
+/// Spacing property value for a node (default 4).
+fn spacing(render: &RenderTree, id: u32) -> i32 {
+    render
+        .node(id)
+        .and_then(|n| n.properties.get(&pathland_opcode::property_id::SPACING))
+        .map(|b| f32::from_bits(*b) as i32)
+        .unwrap_or(4)
+}
+
+/// Apply color/font-size text style from properties via Pango attributes.
+fn apply_text_style(label: &Label, render: &RenderTree, id: u32) {
+    let node = render.node(id).unwrap();
+    let attrs = pango::AttrList::new();
+    if let Some(fs) = node.properties.get(&pathland_opcode::property_id::FONT_SIZE) {
+        // Font size is stored in points (f32); pango scales points to device units.
+        let pts = f32::from_bits(*fs).max(0.0) as i32 * 1000;
+        attrs.insert(pango::AttrSize::new(pts));
+    }
+    if let Some(color) = node.properties.get(&pathland_opcode::property_id::COLOR) {
+        let c = *color;
+        let red = (((c >> 16) & 0xFF) as u16) * 257;
+        let green = (((c >> 8) & 0xFF) as u16) * 257;
+        let blue = ((c & 0xFF) as u16) * 257;
+        let mut fg = pango::AttrColor::new_foreground(red, green, blue);
+        fg.set_start_index(0);
+        fg.set_end_index(u32::MAX);
+        attrs.insert(fg);
+    }
+    label.set_attributes(Some(&attrs));
+}
+
+/// The app handler: the guest routes raw inputs back here.
+///
+/// In this demo the counter is incremented and the tree re-rendered on click.
+/// The handler is a trace point demonstrating the event round-trip: the guest
+/// invokes this after `input.dispatch`, so an EVENT opcode flows host -> guest
+/// -> host through the protocol.
+struct DemoApp;
+
+impl pathland_wit_host::AppHandler for DemoApp {
+    fn on_event(&mut self, _event: &Event) {}
+}

Index: lib/rust/crates/pathland-guest/src/lib.rs
===================================================================
--- lib/rust/crates/pathland-guest/src/lib.rs	
+++ lib/rust/crates/pathland-guest/src/lib.rs	
@@ -1,247 +1,253 @@
 //! # pathland-guest
 //!
 //! The Pathland **WASM guest component**. It owns the canonical retained view
 //! tree and the diff-based engine, and exposes the flat, language-agnostic
 //! `pathland:view/pathland` world:
 //!
 //! - **`builder`** — build/update the retained tree by node id.
 //! - **`engine`** — frame lifecycle + `emit` (writes delta opcodes into the
 //!   ring/arena in linear memory) and `take-batch` (returns the pending frame
 //!   as a network batch).
 //! - **`input`** — raw-input event ingress from the host; routed back to the
 //!   host's `app.on-event` callback.
 //!
 //! Any WIT host (GTK desktop, future Java/Quarkus) drives this component; each
 //! language wraps the world in its own ergonomic surface.
+//!
+//! This crate is built as a WASM component with `cargo component build
+//! -p pathland-guest`. For the native workspace build it compiles to an empty
+//! crate (the implementation is gated on `target_arch = "wasm32"`).

+#![cfg(target_arch = "wasm32")]
+
 use std::collections::{BTreeMap, HashMap};
 use std::sync::Mutex;

 use pathland_engine::Engine;
 use pathland_opcode::property_id;
 use pathland_opcode::{init_memory, Guest as RingGuest, Host, MemoryLayout, Opcode};
 use pathland_transport::BatchEncoder;
 use pathland_view::Node;

 #[allow(warnings)]
 mod bindings;

 use bindings::exports::pathland::view::builder::Guest as BuilderGuest;
 use bindings::exports::pathland::view::engine::Guest as EngineGuest;
 use bindings::exports::pathland::view::input::Guest as InputGuest;
 use bindings::pathland::view::types::{Component, Event, Property};

 /// A flat node in the guest's retained tree (id → node).
 #[derive(Clone)]
 struct FlatNode {
     id: u32,
     view_component: pathland_view::Component,
     properties: BTreeMap<u16, u32>,
     parent: Option<u32>,
     children: Vec<u32>,
 }

 /// The guest component state: retained tree, engine, ring memory.
 ///
 /// The WIT exports are stateless functions, so state lives in a global mutex
 /// (the component model is single-threaded per instance; a plain `static`
 /// would also work, but `Mutex` keeps the borrow checker happy).
 struct State {
     nodes: HashMap<u32, FlatNode>,
     engine: Engine,
     mem: Vec<u8>,
     layout: MemoryLayout,
     encoder: BatchEncoder,
 }

 static STATE: Mutex<Option<State>> = Mutex::new(None);

 fn state() -> &'static Mutex<Option<State>> {
     &STATE
 }

 /// Initialize the guest state (idempotent).
 fn ensure_state() {
     let mut guard = state().lock().unwrap();
     if guard.is_none() {
         let layout = MemoryLayout::default();
         let mut mem = vec![0u8; layout.total_bytes()];
         init_memory(&mut mem, &layout);
         *guard = Some(State {
             nodes: HashMap::new(),
             engine: Engine::new(),
             mem,
             layout,
             encoder: BatchEncoder::new(),
         });
     }
 }

 /// Map a WIT component to a `pathland_view::Component`.
 fn to_view_component(c: &Component) -> pathland_view::Component {
     match c {
         Component::Hstack => pathland_view::Component::HStack,
         Component::Vstack => pathland_view::Component::VStack,
         Component::Text => pathland_view::Component::Text { text: String::new() },
         Component::Button => pathland_view::Component::Button { label: String::new() },
         Component::Spacer => pathland_view::Component::Spacer,
     }
 }

 /// Map a WIT property to a protocol property id.
 fn to_property_id(p: &Property) -> u16 {
     match p {
         Property::Spacing => property_id::SPACING,
         Property::Padding => property_id::PADDING,
         Property::FontSize => property_id::FONT_SIZE,
         Property::Color => property_id::COLOR,
         Property::BackgroundColor => property_id::BACKGROUND_COLOR,
     }
 }

 /// Materialize a `pathland_view::Node` tree rooted at `root_id`, pre-order.
 fn materialize(nodes: &HashMap<u32, FlatNode>, root_id: u32) -> Option<Node> {
     let flat = nodes.get(&root_id)?.clone();
     let mut node = Node::from_component(&flat.view_component);
     node.id = flat.id;
     node.properties = flat.properties.clone();
     for child_id in &flat.children {
         if let Some(child) = materialize(nodes, *child_id) {
             node.children.push(child);
         }
     }
     Some(node)
 }

 /// The root is the node without a parent (the app authors a single root).
 fn root_id(nodes: &HashMap<u32, FlatNode>) -> Option<u32> {
     nodes
         .values()
         .find(|n| n.parent.is_none())
         .map(|n| n.id)
 }

 impl BuilderGuest for State {
     fn create_node(id: u32, component: Component) {
         ensure_state();
         let mut guard = state().lock().unwrap();
         let s = guard.as_mut().unwrap();
         let entry = s.nodes.entry(id).or_insert(FlatNode {
             id,
             view_component: to_view_component(&component),
             properties: BTreeMap::new(),
             parent: None,
             children: Vec::new(),
         });
         entry.view_component = to_view_component(&component);
         entry.properties.clear();
     }

     fn insert_child(parent: u32, child: u32, index: u32) {
         ensure_state();
         let mut guard = state().lock().unwrap();
         let s = guard.as_mut().unwrap();
         if let Some(p) = s.nodes.get_mut(&parent) {
             let idx = if index == u32::MAX {
                 p.children.len()
             } else {
                 (index as usize).min(p.children.len())
             };
             if !p.children.contains(&child) {
                 p.children.insert(idx, child);
             }
         }
         if let Some(c) = s.nodes.get_mut(&child) {
             c.parent = Some(parent);
         }
     }

     fn remove_child(parent: u32, child: u32) {
         ensure_state();
         let mut guard = state().lock().unwrap();
         let s = guard.as_mut().unwrap();
         if let Some(p) = s.nodes.get_mut(&parent) {
             p.children.retain(|c| *c != child);
         }
         if let Some(c) = s.nodes.get_mut(&child) {
             c.parent = None;
         }
     }

     fn set_text(id: u32, text: String) {
         ensure_state();
         let mut guard = state().lock().unwrap();
         let s = guard.as_mut().unwrap();
         if let Some(node) = s.nodes.get_mut(&id) {
             match &mut node.view_component {
                 pathland_view::Component::Text { text: t } => *t = text,
                 pathland_view::Component::Button { label } => *label = text,
                 _ => {}
             }
         }
     }

     fn set_property(id: u32, property: Property, value: f32) {
         ensure_state();
         let mut guard = state().lock().unwrap();
         let s = guard.as_mut().unwrap();
         if let Some(node) = s.nodes.get_mut(&id) {
             let pid = to_property_id(&property);
             if property == Property::Color || property == Property::BackgroundColor {
                 node.properties.insert(pid, value as u32);
             } else {
                 node.properties.insert(pid, value.to_bits());
             }
         }
     }
 }

 impl EngineGuest for State {
     fn begin_frame() {
         ensure_state();
     }

     fn emit() {
         ensure_state();
         let mut guard = state().lock().unwrap();
         let s = guard.as_mut().unwrap();
         let root = root_id(&s.nodes).and_then(|r| materialize(&s.nodes, r));
         if let Some(root) = root {
             let mut ring = RingGuest::new(&mut s.mem, &s.layout);
             ring.begin_frame();
             s.engine.emit(&root, &mut ring).ok();
             ring.end_frame();
         }
     }

     fn end_frame() {}

     fn take_batch() -> Vec<u8> {
         ensure_state();
         let mut guard = state().lock().unwrap();
         let s = guard.as_mut().unwrap();
         // Drain completed frames from the ring and encode them as a batch.
         let mut host = Host::new(&mut s.mem, &s.layout);
         let mut bytes = Vec::new();
         for frame in host.frames() {
             let opcodes: Vec<Opcode> = frame.opcodes().collect();
             let arena = frame.arena().to_vec();
             let frame_count = host.frame_count();
             bytes.extend(s.encoder.encode(frame_count, &opcodes, &arena));
         }
         bytes
     }
 }

