fn import_node(
    builder: &exports::pathland::view::builder::Guest,
    store: &mut Store<Box<dyn AppHandler>>,
    node: &Node,
) -> Result<(), HostError> {
    let store = &mut *store;
    builder.call_create_node(store, node.id, to_wit_component(&node.component))?;
    match &node.component {
        pathland_view::Component::Text { text } => {
            builder.call_set_text(store, node.id, text.as_str())?;
        }
        pathland_view::Component::Button { label } => {
            builder.call_set_text(store, node.id, label.as_str())?;
        }
        _ => {}
    }
    for (pid, value) in &node.properties {
        if let Some(prop) = to_wit_property(*pid) {
            let f = match *pid {
                property_id::COLOR | property_id::BACKGROUND_COLOR => *value as f32,
                _ => f32::from_bits(*value),
            };
            builder.call_set_property(store, node.id, prop, f)?;
        }
    }
    for child in &node.children {
        builder.call_insert_child(store, node.id, child.id, u32::MAX)?;
        import_node(builder, store, child)?;
    }
    Ok(())
}

