#[test]
fn dispatch_routes_event_back_to_host() {
    use std::cell::Cell;

    struct Capture(Cell<Option<Event>>);
    impl AppHandler for Capture {
        fn on_event(&mut self, event: &Event) {
            self.0.set(Some(event.clone()));
        }
    }

    let mut host = GuestHost::new(
        &component_bytes(),
        Capture(Cell::new(None)),
    )
    .unwrap();
    let event = Event::PointerDown((
        1,
        types::Point {
            x: 10.0,
            y: 20.0,
            secondary: false,
        },
    ));
    host.dispatch(&event).unwrap();
    let got = host.app().on_event_and_get();
    assert!(matches!(got, Event::PointerDown(_)));
}

