//! # Pathland GTK4 desktop demo
//!
//! A native GTK4 app that consumes the Pathland components through the WIT
//! world. The developer authors the UI with the SwiftUI-style DSL; the tree
//! flows through the bridge into the WASM guest component (`pathland-guest`),
//! which emits declarative opcodes. The host decodes the emitted batch into a
//! `RenderTree` and renders it with GTK widgets — no host-side reimplementation
//! of layout.
//!
//! Interaction: the button dispatches a raw `EVENT` into the guest, which routes
//! it back to the app via `app.on-event`; the app re-authors the DSL tree and
//! re-emits, so the guest diffs and the renderer updates.

use std::cell::RefCell;
use std::rc::Rc;

use gtk::prelude::*;
use gtk::{Align, Application, ApplicationWindow, Box as GtkBox, Label, Orientation};
use pathland_host::RenderTree;
use pathland_transport::BatchDecoder;
use pathland_view::{assign_ids, button, hstack, text, vstack, Node, View, ViewExt};
use pathland_wit_host::{types, AppHandler, Event, GuestHost};

/// Component bytes are built by `cargo component build -p pathland-guest`.
const GUEST_WASM: &str =
    concat!(env!("CARGO_MANIFEST_DIR"), "/../target/wasm32-wasip1/debug/pathland_guest.wasm");

const APP_ID: &str = "org.pathland.GtkDemo";

/// The demo application state: owns the guest host and the current tree.
struct Demo {
    host: Option<GuestHost>,
    tree: Node,
    count: u32,
}

impl Demo {
    fn new() -> Self {
        Self {
            host: None,
            tree: Node::from_component(&pathland_view::Component::VStack),
            count: 0,
        }
    }

    /// Build the DSL tree for the current counter value.
    fn build_tree(&self) -> Node {
        // The developer's authoring surface — core views (WIT) and custom views
        // are indistinguishable here.
        vstack![
            hstack![
                text(format!("Count: {}", self.count).as_str()),
                button("Increment"),
            ]
            .padding(16.0),
            text("Pathland · GTK4 · WIT").color(0xFF_888888),
        ]
        .padding(24.0)
        .build()
    }

    /// Render the current tree: DSL -> bridge -> guest -> emit -> batch ->
    /// decode -> RenderTree, then build/refresh GTK widgets.
    fn render(&mut self, root: &mut GtkBox) {
        self.tree = self.build_tree();
        assign_ids(&mut self.tree, &mut 1);

        let host = self.host.as_mut().expect("host not initialized");
        host.import_tree(&self.tree).unwrap();
        let batch = host.emit().unwrap();

        // Decode the emitted batch and build the host's native-element description.
        let mut decoder = BatchDecoder::new();
        let mut render = RenderTree::default();
        let batch = decoder.decode(&batch).unwrap();
        render.apply_frame(batch.as_frame());

        // Clear the container and rebuild the widget hierarchy from the
        // RenderTree (the renderer's own output cache).
        for child in root.children() {
            root.remove(&child);
        }
        if let Some(root_node_id) = render.root().map(|n| n.id) {
            let widget = render_node(&render, root_node_id);
            root.append(&widget);
        }
    }
}

/// Build a GTK widget subtree for a node id from the `RenderTree`.
fn render_node(render: &RenderTree, id: u32) -> gtk::Widget {
    let node = render.node(id).unwrap();
    match node.component_type {
        pathland_opcode::component_type::VSTACK => {
            let bx = GtkBox::new(Orientation::Vertical, spacing(render, id));
            bx.set_halign(Align::Fill);
            bx.set_valign(Align::Fill);
            for child in &node.children {
                bx.append(&render_node(render, *child));
            }
            bx.upcast()
        }
        pathland_opcode::component_type::HSTACK => {
            let bx = GtkBox::new(Orientation::Horizontal, spacing(render, id));
            bx.set_halign(Align::Center);
            bx.set_valign(Align::Center);
            for child in &node.children {
                bx.append(&render_node(render, *child));
            }
            bx.upcast()
        }
        pathland_opcode::component_type::TEXT => {
            let label = Label::new(Some(node.text.as_deref().unwrap_or("")));
            apply_text_style(&label, render, id);
            label.upcast()
        }
        pathland_opcode::component_type::BUTTON => {
            let btn = gtk::Button::with_label(node.text.as_deref().unwrap_or(""));
            btn.connect_clicked(move |_| {});
            // Click routing is wired in `setup_button` (dispatch + re-render).
            btn.upcast()
        }
        _ => Label::new(Some("")).upcast(),
    }
}

/// Spacing property value for a node (default 4).
fn spacing(render: &RenderTree, id: u32) -> i32 {
    render
        .node(id)
        .and_then(|n| n.properties.get(&pathland_opcode::property_id::SPACING))
        .map(|b| f32::from_bits(*b) as i32)
        .unwrap_or(4)
}

/// Apply color/font-size text style from properties via Pango attributes.
fn apply_text_style(label: &Label, render: &RenderTree, id: u32) {
    let node = render.node(id).unwrap();
    let mut attrs = pango::AttrList::new();
    if let Some(fs) = node.properties.get(&pathland_opcode::property_id::FONT_SIZE) {
        let size = (f32::from_bits(*fs) * pango::SCALE) as i32;
        attrs.insert(pango::AttrInt::new_size(size));
    }
    if let Some(color) = node.properties.get(&pathland_opcode::property_id::COLOR) {
        let c = *color;
        let rgb = gdk::RGBA::new(
            ((c >> 16) & 0xFF) as f32 / 255.0,
            ((c >> 8) & 0xFF) as f32 / 255.0,
            (c & 0xFF) as f32 / 255.0,
            ((c >> 24) & 0xFF) as f32 / 255.0,
        );
        let mut fg = pango::AttrColor::new_foreground(&rgb.to_color());
        fg.set_start_index(0);
        fg.set_end_index(u32::MAX);
        attrs.insert(fg);
    }
    label.set_attributes(Some(&attrs));
}

fn main() {
    let app = Application::builder().application_id(APP_ID).build();

    app.connect_activate(build_ui);
    app.run();
}

fn build_ui(app: &Application) {
    let demo = Rc::new(RefCell::new(Demo::new()));

    // Instantiate the guest component (WIT host). Run this once.
    {
        let mut d = demo.borrow_mut();
        let bytes = std::fs::read(GUEST_WASM).expect("run `cargo component build` first");
        d.host = Some(GuestHost::new(&bytes, DemoApp).unwrap());
    }

    let window = ApplicationWindow::builder()
        .application(app)
        .title("Pathland GTK4 Demo")
        .default_width(420)
        .default_height(220)
        .build();

    let root = GtkBox::new(Orientation::Vertical, 0);
    window.set_child(Some(&root));

    // Initial render.
    demo.borrow_mut().render(&root);

    // Wire the button: on click, dispatch an EVENT into the guest (routed back
    // to the app via app.on-event) and re-render.
    let demo_click = Rc::clone(&demo);
    let root_click = root.clone();
    root.connect_click_child(move |_rx, child| {
        if child.is::<gtk::Button>() {
            let mut d = demo_click.borrow_mut();
            if let Some(host) = d.host.as_mut() {
                let event = types::Event::PointerDown((
                    0,
                    types::Point {
                        x: 0.0,
                        y: 0.0,
                        secondary: false,
                    },
                ));
                host.dispatch(&event).unwrap();
            }
            d.render(&root_click);
        }
    });

    window.present();
}

/// The app handler: the guest routes events back here.
struct DemoApp;

impl AppHandler for DemoApp {
    fn on_event(&mut self, event: &Event) {
        let _ = event; // The click is handled on the host side in build_ui.
    }
}

//! # Pathland GTK4 desktop demo
//!
//! A native GTK4 app that consumes the Pathland components through the WIT
//! world. The developer authors the UI with the SwiftUI-style DSL; the tree
//! flows through the bridge into the WASM guest component (`pathland-guest`),
//! which emits declarative opcodes. The host decodes the emitted batch into a
//! `RenderTree` and renders it with GTK widgets — no host-side reimplementation
//! of layout.
//!
//! Interaction: the button click dispatches a raw `EVENT` into the guest, which
//! routes it back to the app via `app.on-event`; the app re-authors the DSL
//! tree and re-emits, so the guest diffs and the renderer updates.

use std::cell::{Cell, RefCell};
use std::rc::Rc;

use gtk::prelude::*;
use gtk::{Align, Application, ApplicationWindow, Box as GtkBox, Label, Orientation};
use pathland_host::RenderTree;
use pathland_transport::BatchDecoder;
use pathland_view::{assign_ids, button, hstack, text, vstack, Node, View, ViewExt};
use pathland_wit_host::{types, Event, GuestHost};

/// Component bytes are built by `cargo component build -p pathland-guest`.
const GUEST_WASM: &str =
    concat!(env!("CARGO_MANIFEST_DIR"), "/../target/wasm32-wasip1/debug/pathland_guest.wasm");

const APP_ID: &str = "org.pathland.GtkDemo";

/// Build the DSL tree for the current counter value. This is the developer's
/// authoring surface — core views (WIT) and custom views are indistinguishable.
fn build_tree(count: u32) -> Node {
    vstack![
        hstack![
            text(format!("Count: {}", count).as_str()),
            button("Increment"),
        ]
        .padding(16.0),
        text("Pathland · GTK4 · WIT").color(0xFF_888888),
    ]
    .padding(24.0)
    .build()
}

/// Shared demo state: the guest host, the current count, and the root box.
struct Demo {
    host: Option<GuestHost>,
    count: u32,
}

fn main() {
    let app = Application::builder().application_id(APP_ID).build();
    app.connect_activate(build_ui);
    app.run();
}

fn build_ui(app: &Application) {
    let demo = Rc::new(RefCell::new(Demo {
        host: None,
        count: 0,
    }));

    // Instantiate the guest component (WIT host).
    {
        let bytes = std::fs::read(GUEST_WASM).expect("run `cargo component build` first");
        demo.borrow_mut().host = Some(GuestHost::new(&bytes, DemoApp).unwrap());
    }

    let window = ApplicationWindow::builder()
        .application(app)
        .title("Pathland GTK4 Demo")
        .default_width(420)
        .default_height(220)
        .build();

    let root = GtkBox::new(Orientation::Vertical, 0);
    window.set_child(Some(&root));

    // Re-render the current tree through the full pipeline.
    let demo_t = Rc::clone(&demo);
    let root_t = root.clone();
    let mut re_render = move || render(&demo_t, &root_t);

    re_render();

    // Wire the button click: dispatch an EVENT into the guest (routed back to
    // the app via app.on-event), then re-render.
    let demo_c = Rc::clone(&demo);
    let root_c = root.clone();
    root.connect_click_child(move |_, child| {
        if child.is::<gtk::Button>() {
            if let Some(host) = demo_c.borrow_mut().host.as_mut() {
                let event = types::Event::PointerDown((
                    0,
                    types::Point {
                        x: 0.0,
                        y: 0.0,
                        secondary: false,
                    },
                ));
                let _ = host.dispatch(&event);
            }
            render(&demo_c, &root_c);
        }
    });

    window.present();
}

/// Run the pipeline: DSL -> bridge -> guest -> emit -> batch -> decode ->
/// RenderTree, then rebuild the GTK widget hierarchy.
fn render(demo: &Rc<RefCell<Demo>>, root: &GtkBox) {
    let mut d = demo.borrow_mut();
    let tree = build_tree(d.count);
    let mut tree = tree;
    assign_ids(&mut tree, &mut 1);

    let host = d.host.as_mut().expect("host not initialized");
    host.import_tree(&tree).unwrap();
    let batch = host.emit().unwrap();

    let mut decoder = BatchDecoder::new();
    let mut render = RenderTree::default();
    let batch = decoder.decode(&batch).unwrap();
    render.apply_frame(batch.as_frame());

    // Rebuild the widget hierarchy from the RenderTree.
    for child in root.children() {
        root.remove(&child);
    }
    if let Some(root_node_id) = render.root().map(|n| n.id) {
        root.append(&render_node(&render, root_node_id));
    }
    root.show();
}

/// Build a GTK widget subtree for a node id from the `RenderTree`.
fn render_node(render: &RenderTree, id: u32) -> gtk::Widget {
    let node = render.node(id).unwrap();
    match node.component_type {
        pathland_opcode::component_type::VSTACK => {
            let bx = GtkBox::new(Orientation::Vertical, spacing(render, id));
            bx.set_halign(Align::Fill);
            bx.set_valign(Align::Fill);
            for child in &node.children {
                bx.append(&render_node(render, *child));
            }
            bx.upcast()
        }
        pathland_opcode::component_type::HSTACK => {
            let bx = GtkBox::new(Orientation::Horizontal, spacing(render, id));
            bx.set_halign(Align::Center);
            bx.set_valign(Align::Center);
            for child in &node.children {
                bx.append(&render_node(render, *child));
            }
            bx.upcast()
        }
        pathland_opcode::component_type::TEXT => {
            let label = Label::new(Some(node.text.as_deref().unwrap_or("")));
            apply_text_style(&label, render, id);
            label.upcast()
        }
        pathland_opcode::component_type::BUTTON => {
            gtk::Button::with_label(node.text.as_deref().unwrap_or("")).upcast()
        }
        _ => Label::new(Some("")).upcast(),
    }
}

/// Spacing property value for a node (default 4).
fn spacing(render: &RenderTree, id: u32) -> i32 {
    render
        .node(id)
        .and_then(|n| n.properties.get(&pathland_opcode::property_id::SPACING))
        .map(|b| f32::from_bits(*b) as i32)
        .unwrap_or(4)
}

/// Apply color/font-size text style from properties via Pango attributes.
fn apply_text_style(label: &Label, render: &RenderTree, id: u32) {
    let node = render.node(id).unwrap();
    let mut attrs = pango::AttrList::new();
    if let Some(fs) = node.properties.get(&pathland_opcode::property_id::FONT_SIZE) {
        let size = (f32::from_bits(*fs) * pango::SCALE) as i32;
        attrs.insert(pango::AttrInt::new_size(size));
    }
    if let Some(color) = node.properties.get(&pathland_opcode::property_id::COLOR) {
        let c = *color;
        let rgb = gdk::RGBA::new(
            ((c >> 16) & 0xFF) as f32 / 255.0,
            ((c >> 8) & 0xFF) as f32 / 255.0,
            (c & 0xFF) as f32 / 255.0,
            ((c >> 24) & 0xFF) as f32 / 255.0,
        );
        let mut fg = pango::AttrColor::new_foreground(&rgb.to_color());
        fg.set_start_index(0);
        fg.set_end_index(u32::MAX);
        attrs.insert(fg);
    }
    label.set_attributes(Some(&attrs));
}

/// The app handler: the guest routes raw inputs back here.
///
/// In this demo the UI interaction is driven host-side on click, so the handler
/// is a trace point demonstrating the event round-trip through the protocol.
struct DemoApp;

impl pathland_wit_host::AppHandler for DemoApp {
    fn on_event(&mut self, _event: &Event) {}
}

