// Wire the button click. The click: (1) dispatches an EVENT into the guest
// (routed back via app.on-event — demonstrating the protocol round-trip),
// (2) applies the app's state change (increment count), and (3) re-renders.
let demo_click = Rc::clone(&demo);
let root_click = root.clone();
root.connect_click_child(move |_bx, child| {
    if child.is::<gtk::Button>() {
        let mut d = demo_click.borrow_mut();
        // 1. Dispatch the raw input into the guest (host -> guest).
        let event = types::Event::PointerDown((
            0,
            types::Point {
                x: 0.0,
                y: 0.0,
                secondary: false,
            },
        ));
        let _ = d.host.dispatch(&event);
        // 2. Apply the app's state change.
        d.count = d.count.wrapping_add(1);
    }
    render(&demo_click, &root_click);
});

