    let mut d = demo.borrow_mut();
    let on_click: Option<Rc<dyn Fn()>> = d.on_click.clone();
    let mut tree = build_tree(d.count);
    assign_ids(&mut tree, &mut 1);

    // Disjoint field borrows: engine (producer state) and ring (transport).
    let Demo {
