package pathland;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * A node in the retained view tree (mirrors {@code pathland_view::Node}).
 *
 * @param id         stable node id (assigned by {@code Bridge} / {@code assignIds})
 * @param component  raw protocol component id (hstack/vstack/text/button/spacer)
 * @param children   ordered child node ids
 * @param properties propertyId -> f32 value bits (floats for spacing/padding/size;
 *                   colors stored as raw AARRGGBB bits)
 */
public final class Node {
    public int id;
    public int component;
    public final List<Node> children = new ArrayList<>();
    public final Map<Integer, Float> properties = new LinkedHashMap<>();

    public Node(int id, int component) {
        this.id = id;
        this.component = component;
    }
}

package pathland;

/**
 * A composable view (mirrors {@code pathland_view::View}).
 *
 * Implementations build a {@link Node} subtree. Custom views and core (Rust)
 * views are indistinguishable here — both resolve to the same {@code Node}.
 */
public interface View {
    /** Build the retained node for this view. */
    Node build();

    // --- chainable modifiers (any view, any order, innermost-first) ---

    default View spacing(float value) {
        return new Modified(this, PathlandNative.SPACING, value);
    }

    default View padding(float value) {
        return new Modified(this, PathlandNative.PADDING, value);
    }

    default View color(int rgba) {
        return new Modified(this, PathlandNative.COLOR, rgba);
    }

    default View colored(int rgba) {
        return color(rgba);
    }
}

package pathland;

/**
 * A view wrapped by a single modifier (mirrors {@code pathland_view::Modified}).
 *
 * Applying a modifier to an existing view yields a {@code Modified} that applies
 * the inner view's build first, then records the modifier — so chained modifiers
 * apply innermost-first, matching SwiftUI ordering.
 */
final class Modified implements View {
    private final View inner;
    private final int propertyId;
    private final float value;

    Modified(View inner, int propertyId, float value) {
        this.inner = inner;
        this.propertyId = propertyId;
        this.value = value;
    }

    @Override
    public Node build() {
        Node node = inner.build();
        node.properties.put(propertyId, value);
        return node;
    }
}

package pathland;

/**
 * Vertical / horizontal stacks (mirror {@code pathland_view::VStack/HStack}).
 *
 * {@code vstack(children...)} produces a vertical stack; {@code hstack(...)} a
 * horizontal stack. Children are arbitrary {@link View}s. Modifiers chain.
 */
public final class Stacks {

    private Stacks() {}

    /** A vertical stack of the given children. */
    public static View vstack(View... children) {
        return new StackNode(PathlandNative.VSTACK, children);
    }

    /** A horizontal stack of the given children. */
    public static View hstack(View... children) {
        return new StackNode(PathlandNative.HSTACK, children);
    }

    private static final class StackNode implements View {
        private final int component;
        private final View[] children;

        StackNode(int component, View[] children) {
            this.component = component;
            this.children = children;
        }

        @Override
        public Node build() {
            Node node = new Node(0, component);
            for (View child : children) {
                node.children.add(child.build());
            }
            return node;
        }
    }
}

