package pathland;

import com.sun.jna.Pointer;

/**
 * Bridges a Java DSL {@link Node} tree into the flat Rust {@code pathland_native}
 * surface, then emits opcodes into the shared ring.
 *
 * This is the cross-language bridge: the Java DSL (any {@link View}, custom or
 * core) resolves to a {@link Node} tree, which is walked here into the flat
 * {@code pathland_native_create_node} / {@code set_text} / {@code set_property}
 * / {@code insert_child} calls — no per-component wrappers. Custom views and
 * core (Rust) views are indistinguishable.
 */
public final class Bridge {

    private static int nextId = 1;

    private final Pointer host;

    public Bridge(Pointer host) {
        this.host = host;
    }

    /// Assign stable sequential ids (pre-order) to a freshly built tree.
    public void assignIds(Node root) {
        assign(root);
    }

    private void assign(Node node) {
        node.id = nextId++;
        for (Node child : node.children) {
            assign(child);
        }
    }

    /**
     * Send a full DSL tree into the Rust retained tree (flat builder calls),
     * then {@code emit} opcodes into the shared ring.
     */
    public void importTreeAndEmit(Node root) {
        nextId = 1;
        assign(root);
        send(root);
        emit();
    }

    private void send(Node node) {
        PathlandNative.INSTANCE.pathland_native_create_node(host, node.id, node.component);
        if (!node.string.isEmpty()) {
            setText(node);
        }
        for (Node child : node.children) {
            send(child);
            PathlandNative.INSTANCE.pathland_native_insert_child(
                    host, node.id, child.id, Integer.toUnsignedLong(-1));
        }
        for (java.util.Map.Entry<Integer, Float> e : node.properties.entrySet()) {
            PathlandNative.INSTANCE.pathland_native_set_property_f32(
                    host, node.id, e.getKey(), e.getValue());
        }
    }

    /// Set text on a text or button node.
    private void setText(Node node) {
        PathlandNative.INSTANCE.pathland_native_set_text(host, node.id, node.string);
    }

    /// Update just a single node's text (for increments) then emit.
    public void updateTextAndEmit(int id, String text) {
        PathlandNative.INSTANCE.pathland_native_set_text(host, id, text);
        emit();
    }

    /** Emit the retained tree as opcodes into the shared ring. */
    public void emit() {
        PathlandNative.INSTANCE.pathland_native_emit(host);
    }
}

package pathland;

import com.sun.jna.Pointer;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Reads Pathland opcodes **zero-copy** from the shared-memory ring, matching the
 * stable wire layout in {@code pathland-opcode/src/memory.rs} and
 * {@code spec/OPCODE.md}.
 *
 * The driver is shown the raw ring pointer by the Rust host
 * ({@code pathland_native_ring_ptr}); it reads the header (frameCount, cursors,
 * ring/arena offsets) and the 16-byte opcodes in place — no copies, no
 * serialization.
 */
public final class RingReader {

    // Header field offsets (little-endian), see pathland-opcode::memory.
    static final int OFF_RING_OFFSET = 0x06;
    static final int OFF_SLOT_COUNT = 0x0E;
    static final int OFF_ARENA_OFFSET = 0x12;
    static final int OFF_READ_CURSOR = 0x1C;
    static final int OFF_WRITE_CURSOR = 0x20;

    // Categories / commands.
    static final int CAT_TREE = 0x01;
    static final int CAT_STYLE = 0x02;
    static final int CMD_SET_TEXT = 0x03;

    private RingReader() {}

    private static int u32(Pointer p, long off) {
        // little-endian read
        return p.getInt(off);
    }

    private static int u16(Pointer p, long off) {
        return p.getShort(off) & 0xFFFF;
    }

    /** A decoded reference to a tree node's text (from SET_TEXT). */
    public static final class TextEntry {
        public final int id;
        public final String text;
        TextEntry(int id, String text) {
            this.id = id;
            this.text = text;
        }
    }

    /**
     * Read all {@code STYLE:SET_TEXT} entries in the current ring frame,
     * zero-copy.
     */
    public static List<TextEntry> readTextEntries(Pointer mem) {
        List<TextEntry> out = new ArrayList<>();
        int ringOff = u32(mem, OFF_RING_OFFSET);
        int slotCount = u32(mem, OFF_SLOT_COUNT);
        int arenaOff = u32(mem, OFF_ARENA_OFFSET);
        int readCur = u32(mem, OFF_READ_CURSOR);
        int writeCur = u32(mem, OFF_WRITE_CURSOR);
        if (slotCount <= 0) {
            return out;
        }
        int mask = slotCount - 1;
        int n = writeCur - readCur;
        if (n < 0 || n > slotCount) {
            n = 0; // wrapped; ignore for the reference demo
        }
        for (int i = 0; i < n; i++) {
            int slot = (readCur + i) & mask;
            long base = ringOff + (long) slot * 16;
            int cat = mem.getByte(base) & 0xFF;
            int cmd = mem.getByte(base + 1) & 0xFF;
            int nodeA = u32(mem, base + 4);
            int bVal = u32(mem, base + 8);
            if (cat == CAT_STYLE && cmd == CMD_SET_TEXT) {
                out.add(new TextEntry(nodeA, readArenaString(mem, arenaOff, bVal)));
            }
        }
        return out;
    }

    /** Read an arena string at ref: {@code [u32 len][bytes]} (utf-8). */
    private static String readArenaString(Pointer mem, int arenaOff, int ref) {
        long base = arenaOff + (long) ref;
        int len = u32(mem, base);
        byte[] bytes = mem.getByteArray(base + 4, len);
        return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
    }
}

package demo;

import com.sun.jna.Pointer;
import pathland.Bridge;
import pathland.DSL;
import pathland.Node;
import pathland.PathlandNative;
import pathland.RingReader;
import pathland.View;

import javax.swing.*;
import java.awt.*;

/**
 * Pathland Java + Swing desktop demo.
 *
 * Proves the cross-language + zero-copy story for Java:
 *  - a SwiftUI-like DSL authoring surface (pathland.DSL)
 *  - drives Rust components via the flat pathland_native C ABI (no per-component wrappers)
 *  - reads the resulting opcodes zero-copy from the shared-memory ring
 *
 * Run:
 *   PATH="$HOME/.cargo/bin:$PATH" cargo build -p pathland-native
 *   mvn -q -Dpathland.rust.target=<lib/rust/target/debug> compile exec:java
 */
public final class DemoApp {

    // Count text node id: pre-order ids of vstack(hstack(text, button), text) are
    // 1=vstack, 2=hstack, 3=count text, 4=button, 5=status text.
    private static final int COUNT_TEXT_ID = 3;

    private final JLabel countLabel;
    private int count = 0;
    private final Pointer host;
    private final Bridge bridge;

    public DemoApp() {
        host = PathlandNative.INSTANCE.pathland_native_create();
        bridge = new Bridge(host);

        countLabel = new JLabel("Count: 0");
        countLabel.setFont(countLabel.getFont().deriveFont(Font.BOLD, 24f));

        JButton increment = new JButton("Increment");
        increment.addActionListener(e -> clicked());

        JLabel status = new JLabel("Pathland · Java · shared ring");
        status.setForeground(new Color(0x88, 0x88, 0x88));

        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBorder(BorderFactory.createEmptyBorder(24, 24, 24, 24));
        panel.add(centered(countLabel));
        panel.add(Box.createVerticalStrut(12));
        panel.add(centered(increment));
        panel.add(Box.createVerticalStrut(12));
        panel.add(centered(status));

        JFrame frame = new JFrame("Pathland Java Demo");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setContentPane(panel);
        frame.pack();
        frame.setLocationRelativeTo(null);
        frame.setVisible(true);

        render();
    }

    private static JComponent centered(JComponent c) {
        JPanel p = new JPanel();
        p.add(c);
        return p;
    }

    private void clicked() {
        count += 1;
        bridge.updateTextAndEmit(COUNT_TEXT_ID, "Count: " + count);
        render();
    }

    /** Rebuild the tree through the DSL, bridge it, then read opcodes zero-copy. */
    private void render() {
        View root = DSL.vstack(
                DSL.hstack(DSL.text("Count: " + count), DSL.button("Increment")).padding(16f),
                DSL.text("Pathland · Java · shared ring").color(0x888888)
        ).spacing(12f).padding(24f);

        Node tree = root.build();
        bridge.importTreeAndEmit(tree);

        // Zero-copy read: the Rust host returns the shared ring pointer; parse
        // opcodes in place.
        Pointer mem = PathlandNative.INSTANCE.pathland_native_ring_ptr(host);
        for (RingReader.TextEntry e : RingReader.readTextEntries(mem)) {
            if (e.id == COUNT_TEXT_ID) {
                countLabel.setText(e.text);
            }
        }
    }

    private void shutdown() {
        PathlandNative.INSTANCE.pathland_native_destroy(host);
    }

    public static void main(String[] args) {
        final DemoApp app = new DemoApp();
        Runtime.getRuntime().addShutdownHook(new Thread(app::shutdown));
    }
}

