package pathland;

/**
 * Vertical / horizontal stacks (mirror {@code pathland_view::VStack/HStack}).
 *
 * {@code vstack(children...)} produces a vertical stack; {@code hstack(...)} a
 * horizontal stack. Children are arbitrary {@link View}s. Modifiers chain.
 */
public final class Stacks {

    private Stacks() {}

    /** A vertical stack of the given children. */
    public static View vstack(View... children) {
        return new StackNode(PathlandNative.VSTACK, children);
    }

    /** A horizontal stack of the given children. */
    public static View hstack(View... children) {
        return new StackNode(PathlandNative.HSTACK, children);
    }

    private static final class StackNode implements View {
        private final int component;
        private final View[] children;

        StackNode(int component, View[] children) {
            this.component = component;
            this.children = children;
        }

        @Override
        public Node build() {
            Node node = new Node(0, component);
            for (View child : children) {
                node.children.add(child.build());
            }
            return node;
        }
    }
}

